const input = $input.first().json;
const mediaPrompts = input.media_prompts || [];
const courseTitle = input.course_title || '';
const lessonTitle = input.lesson_title || '';

return mediaPrompts.map(mp => ({
  json: {
    type: mp.type || 'illustration',
    prompt: mp.prompt || mp.description || '',
    alt_text: mp.alt_text || '',
    position: mp.position || '',
    course_title: courseTitle,
    lesson_title: lessonTitle
  }
}));

const input = $input.first().json;
let result = { type: '', url: '', mermaid_code: '', html: '', alt_text: '' };

try {
  if (input.candidates) {
    // Gemini response (diagram or infographic)
    const text = input.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    const parsed = JSON.parse(text);
    result.mermaid_code = parsed.mermaid_code || '';
    result.html = parsed.html || '';
    result.alt_text = parsed.alt_text || '';
    result.type = result.mermaid_code ? 'diagram' : 'infographic';
  } else if (input.file_url) {
    // WF-15 response (illustration)
    result.url = input.file_url;
    result.type = 'illustration';
    result.alt_text = input.original_prompt || '';
  }
} catch (e) {
  // continue with empty result
}

return [{ json: result }];
